#!/usr/bin/env python3
"""Generate synthetic CoT for claude-fable-5 Claude Code chats -> SFT dataset.

For every fable-5 agent output block (tool_use or text), reconstruct prior
conversation context and ask Groq gpt-oss-120b to produce the detailed
chain-of-thought that leads to that exact output. gpt-oss puts its own
reasoning in the `reasoning` field; the requested CoT lands in `content`
wrapped in <think></think>. We extract ALL <think> blocks from content and
keep the LAST one (== "second pair": skip model's own meta-CoT).
"""
import json, glob, os, re, sys, time, threading, urllib.request, urllib.error
from concurrent.futures import ThreadPoolExecutor

API_KEY = "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"
MODEL   = "openai/gpt-oss-120b"
URL     = "https://api.groq.com/openai/v1/chat/completions"
TARGET_MODEL = "claude-fable-5"

OUTDIR  = "/home/lane/claude/fable_cot"
OUTFILE = os.path.join(OUTDIR, "fable5_cot_sft.jsonl")
LOGFILE = os.path.join(OUTDIR, "progress.log")

MAX_CTX_CHARS   = 7000   # cap rendered context
MAX_BLOB        = 900    # truncate any single text/result blob
WORKERS         = 10
MAX_RETRY       = 8

SYS_PROMPT = (
    "You are reconstructing the private internal reasoning (chain-of-thought) of an "
    "autonomous coding agent (Claude Code) at one step of a real session. You are given "
    "the conversation context so far and the EXACT output the agent produced next "
    "(either a tool call or a message to the user).\n\n"
    "Write the detailed, first-person internal monologue the agent would have had JUST "
    "BEFORE producing that output. It must:\n"
    "- be long and thorough: weigh the situation, what was just learned, what's unknown, "
    "options considered and rejected, and why this specific action/output is the right next step;\n"
    "- reference concrete details from the context (file names, values, tool results);\n"
    "- flow naturally and inevitably INTO the given output (for a tool call, justify the exact "
    "tool and arguments; for a message, justify exactly what is said);\n"
    "- read like genuine working reasoning, not a summary written after the fact;\n"
    "- NOT mention that it is being asked to do this, and NOT quote these instructions.\n\n"
    "Output ONLY the chain-of-thought, wrapped in a single pair of <think> </think> tags. "
    "Nothing before or after the tags."
)

def trunc(s, n=MAX_BLOB):
    s = s if isinstance(s, str) else json.dumps(s, ensure_ascii=False)
    return s if len(s) <= n else s[:n] + " …[truncated]"

def render_block(b):
    t = b.get("type")
    if t == "text":
        return "ASSISTANT (message): " + trunc(b.get("text", ""))
    if t == "tool_use":
        return "ASSISTANT (tool call) %s input=%s" % (b.get("name"), trunc(b.get("input", {})))
    if t == "tool_result":
        c = b.get("content")
        if isinstance(c, list):
            c = " ".join(x.get("text", "") if isinstance(x, dict) else str(x) for x in c)
        return "TOOL RESULT: " + trunc(c)
    if t == "thinking":
        return ""
    return ""

def render_user_content(c):
    if isinstance(c, str):
        return "USER: " + trunc(c)
    out = []
    for b in c:
        if b.get("type") == "tool_result":
            out.append(render_block(b))
        elif b.get("type") == "text":
            out.append("USER: " + trunc(b.get("text", "")))
    return "\n".join(out)

def extract_last_think(content):
    blocks = re.findall(r"<think>(.*?)</think>", content, re.DOTALL)
    if blocks:
        return blocks[-1].strip()
    # no tags -> strip any stray and return whole
    return content.replace("<think>", "").replace("</think>", "").strip()

def groq_cot(context_str, output_str):
    body = json.dumps({
        "model": MODEL,
        "temperature": 0.7,
        "reasoning_effort": "low",
        "max_tokens": 2048,
        "messages": [
            {"role": "system", "content": SYS_PROMPT},
            {"role": "user", "content":
                "CONVERSATION CONTEXT SO FAR:\n" + context_str +
                "\n\n=== THE EXACT OUTPUT THE AGENT PRODUCED NEXT ===\n" + output_str +
                "\n\nWrite the detailed chain-of-thought that leads to exactly this output."},
        ],
    }).encode()
    last = None
    for attempt in range(MAX_RETRY):
        try:
            req = urllib.request.Request(URL, data=body, headers={
                "Authorization": "Bearer " + API_KEY,
                "Content-Type": "application/json",
                "User-Agent": "curl/8.5.0",
            })
            with urllib.request.urlopen(req, timeout=120) as r:
                o = json.loads(r.read())
            content = o["choices"][0]["message"].get("content", "")
            return extract_last_think(content)
        except urllib.error.HTTPError as e:
            last = e
            if e.code == 429:
                ra = e.headers.get("retry-after")
                try:
                    wait = float(ra) if ra else None
                except ValueError:
                    wait = None
                if wait is None:
                    rt = e.headers.get("x-ratelimit-reset-tokens", "")
                    mt = re.match(r"([\d.]+)", rt or "")
                    wait = float(mt.group(1)) if mt else min(2 ** attempt, 30)
                time.sleep(min(wait + 0.5, 65))
                continue
            if e.code in (500, 502, 503):
                time.sleep(min(2 ** attempt, 30)); continue
            time.sleep(2 ** attempt)
        except Exception as e:
            last = e
            time.sleep(min(2 ** attempt, 20))
    raise RuntimeError("groq failed: %s" % last)

# ---- build the work list -------------------------------------------------
def build_steps():
    files = sorted(glob.glob("/home/lane/.claude/projects/**/*.jsonl", recursive=True))
    steps = []
    for f in files:
        # quick check: does file contain target model assistant turns?
        rows = []
        has = False
        try:
            for l in open(f):
                try: o = json.loads(l)
                except: continue
                if o.get("type") in ("user", "assistant"):
                    rows.append(o)
                    if o.get("type") == "assistant" and o.get("message", {}).get("model") == TARGET_MODEL:
                        has = True
        except: continue
        if not has:
            continue
        ctx = []  # rolling rendered lines
        for o in rows:
            m = o.get("message", {})
            role = o.get("type")
            content = m.get("content")
            if role == "user":
                ctx.append(render_user_content(content))
                continue
            # assistant
            is_target = (m.get("model") == TARGET_MODEL)
            if isinstance(content, str):
                content = [{"type": "text", "text": content}]
            for b in content or []:
                bt = b.get("type")
                if bt == "text" and not b.get("text", "").strip():
                    continue
                if bt in ("text", "tool_use") and is_target:
                    # this block is a training target
                    ctx_join = "\n".join(x for x in ctx if x)
                    if len(ctx_join) > MAX_CTX_CHARS:
                        ctx_join = "…[earlier truncated]…\n" + ctx_join[-MAX_CTX_CHARS:]
                    steps.append({
                        "file": f,
                        "session": os.path.basename(f).replace(".jsonl", ""),
                        "context": ctx_join,
                        "output_type": bt,
                        "output": ({"text": b.get("text")} if bt == "text"
                                   else {"tool": b.get("name"), "input": b.get("input")}),
                    })
                # append this block to context for subsequent steps
                line = render_block(b)
                if line:
                    ctx.append(line)
        # end file
    return steps

# ---- main ----------------------------------------------------------------
def output_render(step):
    if step["output_type"] == "text":
        return "ASSISTANT (message): " + step["output"]["text"]
    return "ASSISTANT (tool call) %s input=%s" % (
        step["output"]["tool"], json.dumps(step["output"]["input"], ensure_ascii=False))

def main():
    os.makedirs(OUTDIR, exist_ok=True)
    steps = build_steps()
    # key each step
    for i, s in enumerate(steps):
        s["uid"] = "%s#%d" % (s["session"], i)
    done = set()
    if os.path.exists(OUTFILE):
        for l in open(OUTFILE):
            try: done.add(json.loads(l)["uid"])
            except: pass
    todo = [s for s in steps if s["uid"] not in done]
    total = len(steps)
    log = open(LOGFILE, "a")
    log.write("START total=%d done=%d todo=%d\n" % (total, len(done), len(todo))); log.flush()
    print("total=%d done=%d todo=%d" % (total, len(done), len(todo)), flush=True)

    lock = threading.Lock()
    out = open(OUTFILE, "a")
    counter = {"n": len(done), "err": 0}

    def work(step):
        out_str = output_render(step)
        try:
            cot = groq_cot(step["context"], out_str)
        except Exception as e:
            with lock:
                counter["err"] += 1
                log.write("ERR %s %s\n" % (step["uid"], e)); log.flush()
            return
        rec = {
            "uid": step["uid"],
            "source_file": step["file"],
            "session": step["session"],
            "model": TARGET_MODEL,
            "context": step["context"],
            "cot": cot,
            "output_type": step["output_type"],
            "output": step["output"],
            # ready-to-train assembly
            "completion": "<think>\n%s\n</think>\n%s" % (cot, out_str),
        }
        with lock:
            out.write(json.dumps(rec, ensure_ascii=False) + "\n"); out.flush()
            counter["n"] += 1
            if counter["n"] % 25 == 0:
                msg = "progress %d/%d err=%d" % (counter["n"], total, counter["err"])
                log.write(msg + "\n"); log.flush()
                print(msg, flush=True)

    with ThreadPoolExecutor(max_workers=WORKERS) as ex:
        list(ex.map(work, todo))

    log.write("DONE n=%d err=%d\n" % (counter["n"], counter["err"])); log.flush()
    print("DONE n=%d err=%d" % (counter["n"], counter["err"]), flush=True)

if __name__ == "__main__":
    main()

