#!/usr/bin/env python3
"""Re-generate CoT for the truncated records in fable5_cot_merged.jsonl.

The original gen_cot*.py capped context blobs (MAX_BLOB=900), total context
(MAX_CTX_CHARS=7000) and CoT output (max_tokens=2048). ~344 records had their
`cot` cut off mid-sentence. This script:

  1. finds every truncated record in the merged file,
  2. rebuilds its step from the ORIGINAL source jsonl producing BOTH the old
     truncated-context (to match the record 1:1) and the FULL untruncated
     context,
  3. re-asks Groq for a full CoT (no max_tokens cap that bites),
  4. rewrites context + cot + completion in place -> a new merged file.

Run with --dry-run to only verify matching coverage (no API calls).
"""
import json, glob, os, re, sys, time, threading, urllib.request, urllib.error
from concurrent.futures import ThreadPoolExecutor

API_KEY = "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"
MODEL   = "openai/gpt-oss-120b"
URL     = "https://api.groq.com/openai/v1/chat/completions"
TARGET_MODEL = "claude-fable-5"

OUTDIR   = "/home/lane/claude/fable_cot"
MERGED   = os.path.join(OUTDIR, "fable5_cot_merged.jsonl")
OUTFILE  = os.path.join(OUTDIR, "fable5_cot_merged.full.jsonl")  # rewritten merged
SIDECAR  = os.path.join(OUTDIR, "recot_full.jsonl")              # resumable cache: uid->cot
LOGFILE  = os.path.join(OUTDIR, "recot_progress.log")

SRC_GLOBS = [
    "/home/lane/.claude/projects/**/*.jsonl",   # local
    "/home/lane/claude/hf_fable5_ds/*.jsonl",   # hf (TeichAI)
]

# old truncation params (to REPRODUCE the stored truncated context for matching)
OLD_MAX_BLOB = 900
OLD_MAX_CTX  = 7000

MAX_OUT_TOKENS = 8192   # full CoT, no practical cap
WORKERS        = 8
MAX_RETRY      = 8

SYS_PROMPT = (
    "You are reconstructing the private internal reasoning (chain-of-thought) of an "
    "autonomous coding agent (Claude Code) at one step of a real session. You are given "
    "the conversation context so far and the EXACT output the agent produced next "
    "(either a tool call or a message to the user).\n\n"
    "Write the detailed, first-person internal monologue the agent would have had JUST "
    "BEFORE producing that output. It must:\n"
    "- be long and thorough: weigh the situation, what was just learned, what's unknown, "
    "options considered and rejected, and why this specific action/output is the right next step;\n"
    "- reference concrete details from the context (file names, values, tool results);\n"
    "- flow naturally and inevitably INTO the given output (for a tool call, justify the exact "
    "tool and arguments; for a message, justify exactly what is said);\n"
    "- read like genuine working reasoning, not a summary written after the fact;\n"
    "- NOT mention that it is being asked to do this, and NOT quote these instructions.\n\n"
    "Output ONLY the chain-of-thought, wrapped in a single pair of <think> </think> tags. "
    "Nothing before or after the tags."
)

# ---- rendering: parametrised on blob cap so we can build truncated OR full ----
def trunc(s, n):
    s = s if isinstance(s, str) else json.dumps(s, ensure_ascii=False)
    if n is None:
        return s
    return s if len(s) <= n else s[:n] + " …[truncated]"

def render_block(b, blob):
    t = b.get("type")
    if t == "text":
        return "ASSISTANT (message): " + trunc(b.get("text", ""), blob)
    if t == "tool_use":
        return "ASSISTANT (tool call) %s input=%s" % (b.get("name"), trunc(b.get("input", {}), blob))
    if t == "tool_result":
        c = b.get("content")
        if isinstance(c, list):
            c = " ".join(x.get("text", "") if isinstance(x, dict) else str(x) for x in c)
        return "TOOL RESULT: " + trunc(c, blob)
    return ""

def render_user_content(c, blob):
    if isinstance(c, str):
        return "USER: " + trunc(c, blob)
    out = []
    for b in c:
        if b.get("type") == "tool_result":
            out.append(render_block(b, blob))
        elif b.get("type") == "text":
            out.append("USER: " + trunc(b.get("text", ""), blob))
    return "\n".join(out)

def join_ctx(ctx_lines, blob, ctxcap):
    s = "\n".join(x for x in ctx_lines if x)
    if ctxcap is not None and len(s) > ctxcap:
        s = "…[earlier truncated]…\n" + s[-ctxcap:]
